#pragma once
#include "sensor_runtime.hpp"
#include "sensor_keeper.hpp"
#include "native_scene.hpp"
enum class NativeSensorCategory {Player,Ride,Eye,Simple,Map,Character};
class NativeSensorWorld {
    NativeScene scene;SensorHitChecker& checker;bool ticking=false;std::vector<NativeSensorLifecycleHost*> scheduledHosts;std::map<NativeSensorLifecycleHost*,NativeCallbackActor*> hostCallbacks;
    struct DeleteSensor {void operator()(HitSensor* sensor)const{sensor->invalidateBySystem();delete[] sensor->mSensors;delete sensor;}};
    std::vector<std::unique_ptr<HitSensor,DeleteSensor>> sensors;std::array<size_t,6> ownedCounts{};std::vector<std::unique_ptr<NativeSensorKeeper>> keepers;
    std::array<SensorGroup*,6> groups()const{return {checker.mPlayerGroup,checker.mRideGroup,checker.mEyeGroup,checker.mSimpleGroup,checker.mMapObjGroup,checker.mCharacterGroup};}
public:
    NativeSensorWorld():checker(scene.create<SensorHitChecker>("native sensor checker")){}
    NativeSensorCategory categoryForType(u32 type){NativeSensorGroupScope scope(*checker.mCharacterGroup);HitSensor probe(type,0,0,nullptr);checker.initGroup(&probe);auto all=groups();for(size_t i=0;i<all.size();++i)if(probe.mSensorGroup==all[i])return NativeSensorCategory(i);throw std::runtime_error("Unrecognized original sensor group");}
    HitSensor& create(u32 type,u16 contacts,float radius,LiveActor& host){return create(categoryForType(type),type,contacts,radius,host);}
    NativeSensorKeeper& createKeeperForType(u32 type,int capacity){return createKeeper(categoryForType(type),capacity);}
    HitSensor& create(NativeSensorCategory category,u32 type,u16 contacts,float radius,LiveActor& host){
        size_t index=size_t(category);assetCheck(index<6&&std::isfinite(radius)&&radius>=0,"Invalid native sensor creation");auto group=groups()[index];assetCheck(ownedCounts[index]<size_t(group->mMaxSensors),"Native sensor category capacity exceeded");NativeSensorGroupScope scope(*group);std::unique_ptr<HitSensor,DeleteSensor> sensor(new HitSensor(type,contacts,radius,&host));sensor->validateBySystem();auto& result=*sensor;sensors.push_back(std::move(sensor));++ownedCounts[index];return result;
    }
    NativeSensorKeeper& createKeeper(NativeSensorCategory category,int capacity){size_t index=size_t(category);assetCheck(index<6&&capacity>0&&capacity<=2048,"Invalid native keeper reservation");auto group=groups()[index];assetCheck(ownedCounts[index]+size_t(capacity)<=size_t(group->mMaxSensors),"Native sensor category capacity exceeded");auto keeper=std::make_unique<NativeSensorKeeper>(capacity,*group);auto& result=*keeper;keepers.push_back(std::move(keeper));ownedCounts[index]+=size_t(capacity);return result;}
    NativeCallbackActor& scheduleHost(NativeSensorLifecycleHost& host){assetCheck(!ticking,"Host scheduling during world update");bool owned=false;for(auto& keeper:keepers)owned|=keeper.get()==&host.sensorKeeper();assetCheck(owned,"Scheduled lifecycle keeper belongs to another world");for(auto existing:scheduledHosts)assetCheck(existing!=&host&&&existing->sensorKeeper()!=&host.sensorKeeper(),"Duplicate lifecycle host/keeper scheduling");scheduledHosts.push_back(&host);try{hostCallbacks.emplace(&host,nullptr);auto& callback=scene.create<NativeCallbackActor>([&host](){host.dispatchSensors();host.tickNerve();});hostCallbacks.at(&host)=&callback;return callback;}catch(...){hostCallbacks.erase(&host);scheduledHosts.pop_back();throw;}}
    void unscheduleHost(NativeSensorLifecycleHost& host){assetCheck(!ticking,"Host unscheduling during world update");auto found=hostCallbacks.find(&host);assetCheck(found!=hostCallbacks.end(),"Lifecycle host is not scheduled");auto callback=found->second;scene.remove(*callback);hostCallbacks.erase(found);scheduledHosts.erase(std::remove(scheduledHosts.begin(),scheduledHosts.end(),&host),scheduledHosts.end());}
    void removeKeeper(NativeSensorKeeper& keeper){assetCheck(!ticking,"Keeper removal during world update");auto found=std::find_if(keepers.begin(),keepers.end(),[&](const auto& value){return value.get()==&keeper;});assetCheck(found!=keepers.end(),"Keeper is not owned by this world");auto all=groups();size_t category=6;for(size_t i=0;i<6;++i)if(all[i]==&keeper.registeredGroup())category=i;assetCheck(category<6,"Removed keeper has unknown category");size_t capacity=size_t(keeper.reservedCapacity());assetCheck(ownedCounts[category]>=capacity,"Keeper reservation accounting underflow");for(size_t i=scheduledHosts.size();i>0;--i)if(&scheduledHosts[i-1]->sensorKeeper()==&keeper)unscheduleHost(*scheduledHosts[i-1]);for(auto group:all)group->clear();ownedCounts[category]-=capacity;keepers.erase(found);}
    void retireHost(NativeSensorLifecycleHost& host){assetCheck(!ticking,"Host retirement during world update");auto& keeper=host.sensorKeeper();bool owned=false;for(auto& value:keepers)owned|=value.get()==&keeper;assetCheck(owned,"Retired host keeper belongs to another world");host.kill();removeKeeper(keeper);host.detachKeeper();}
    void setType(HitSensor& sensor,u32 type){
        assetCheck(!ticking,"Sensor type mutation during world tick is unsupported");bool owned=false;for(const auto& item:sensors)owned|=item.get()==&sensor;assetCheck(owned,"Sensor is not directly owned by this world");auto all=groups();size_t previous=6;for(size_t i=0;i<6;++i)if(sensor.mSensorGroup==all[i])previous=i;assetCheck(previous<6,"Owned sensor has unknown group");size_t next=size_t(categoryForType(type));if(next!=previous)assetCheck(ownedCounts[next]<size_t(all[next]->mMaxSensors),"Native sensor category capacity exceeded");NativeSensorGroupScope scope(*all[next]);sensor.setType(type);if(next!=previous){--ownedCounts[previous];++ownedCounts[next];}for(auto group:all)group->clear();
    }
    void tick(){assetCheck(!ticking,"Recursive sensor world tick");struct TickScope{bool& flag;explicit TickScope(bool& value):flag(value){flag=true;}~TickScope(){flag=false;}} tickScope(ticking);for(auto& keeper:keepers)keeper->update();for(const auto& sensor:sensors){assetCheck(std::isfinite(sensor->mPosition.x)&&std::isfinite(sensor->mPosition.y)&&std::isfinite(sensor->mPosition.z)&&std::isfinite(sensor->mRadius)&&sensor->mRadius>=0,"Invalid native sensor geometry");}scene.tick();for(auto& keeper:keepers){bool scheduled=false;for(auto host:scheduledHosts)scheduled|=&host->sensorKeeper()==keeper.get();if(!scheduled)keeper->dispatch();}}
    ~NativeSensorWorld(){keepers.clear();sensors.clear();for(auto group:groups()){delete[] group->mSensors;delete group;}}
};
inline void sensorWorldTests(){
    struct Host:LiveActor {bool clipped=false;bool receiveMessage(u32,HitSensor*,HitSensor*)override{return false;}bool isClipped()const override{return clipped;}};Host a,b;NativeSensorWorld world;
    auto& player=world.create(NativeSensorCategory::Player,1,4,1,a);auto& character=world.create(NativeSensorCategory::Character,2,4,1,b);character.mPosition={1,0,0};world.tick();assetCheck(player.mSensorCount==1&&character.mSensorCount==1,"Original sensor sphere overlap failed");
    character.mPosition={2,0,0};world.tick();assetCheck(player.mSensorCount==0&&character.mSensorCount==0,"Original sensor exact tangency accepted");character.mPosition={1,0,0};b.clipped=true;world.tick();assetCheck(player.mSensorCount==0,"Clipped sensor generated contact");b.clipped=false;character.invalidate();world.tick();assetCheck(player.mSensorCount==0,"Invalid sensor generated contact");character.validate();world.tick();assetCheck(player.mSensorCount==1,"Validated sensor did not return");
    auto& sameHost=world.create(NativeSensorCategory::Character,2,4,1,a);world.tick();assetCheck(sameHost.mSensorCount==1,"Same-host sensor exclusion failed");auto& eye=world.create(NativeSensorCategory::Eye,0x7F,4,1,b);world.tick();bool foundEye=false;for(size_t i=0;i<player.mSensorCount;++i)foundEye|=player.mSensors[i]==&eye;assetCheck(!foundEye&&eye.mSensorCount>0,"Original eye sensor one-way contact failed");
    Host capacityHost;NativeSensorWorld bounded;for(int i=0;i<16;++i)bounded.create(NativeSensorCategory::Player,1,1,1,capacityHost);bool rejected=false;try{bounded.create(NativeSensorCategory::Player,1,1,1,capacityHost);}catch(const std::exception&){rejected=true;}assetCheck(rejected,"Native sensor group capacity not enforced");
}

inline void sensorPipelineTests(){
 struct Host:LiveActor {int attacks=0;HitSensor* target=nullptr;bool dead=false;bool receiveMessage(u32,HitSensor*,HitSensor*)override{return false;}bool isDead()const override{return dead;}void attackSensor(HitSensor*,HitSensor* to)override{++attacks;target=to;}};
 Host player,character;NativeSensorWorld world;auto& playerKeeper=world.createKeeper(NativeSensorCategory::Player,1);auto& characterKeeper=world.createKeeper(NativeSensorCategory::Character,1);auto& body=playerKeeper.add("body",1,2,1,player,{});auto& target=characterKeeper.add("body",2,2,1,character,{});playerKeeper.validate();characterKeeper.validate();character.mPosition={1,0,0};world.tick();assetCheck(player.attacks==1&&character.attacks==1&&player.target==&target&&body.mSensorCount==1,"Named sensor overlap dispatch pipeline failed");character.mPosition={5,0,0};world.tick();assetCheck(body.mSensorCount==0&&player.attacks==1,"Sensor pipeline retained stale contacts");character.mPosition={1,0,0};characterKeeper.invalidate();world.tick();assetCheck(player.attacks==1,"Invalid keeper generated contact");characterKeeper.validate();character.dead=true;world.tick();assetCheck(player.attacks==1,"Dead target was attacked in pipeline");character.dead=false;world.tick();assetCheck(player.attacks==2,"Live target did not return to pipeline");
 NativeSensorWorld bounded;bounded.createKeeper(NativeSensorCategory::Player,16);bool rejected=false;try{bounded.create(NativeSensorCategory::Player,1,1,1,player);}catch(const std::exception&){rejected=true;}assetCheck(rejected,"Keeper reservations did not bound mixed sensor ownership");
}

inline void sensorRoutingTests(){
 NativeSensorWorld world;
 for(u32 type=0;type<256;++type){auto expected=NativeSensorCategory::Character;if(type==1)expected=NativeSensorCategory::Player;else if(type>8&&type<0x12)expected=NativeSensorCategory::Ride;else if(type==0x7f)expected=NativeSensorCategory::Eye;else if(type==0x4a||type==0x4c||type==0x15||type==0x47||type==0x1f||(type>0x60&&type<0x6e)||(type>0x6f&&type<0x74))expected=NativeSensorCategory::Simple;else if(type>0x45&&type<0x5f)expected=NativeSensorCategory::Map;assetCheck(world.categoryForType(type)==expected,"Original sensor type routing mismatch");}
 struct Host:LiveActor {bool receiveMessage(u32,HitSensor*,HitSensor*)override{return false;}};Host player,coin;auto& body=world.create(1,2,1,player);auto& item=world.create(0x4a,2,1,coin);world.tick();assetCheck(body.mSensorCount==1&&item.mSensorCount==1,"Automatic sensor routing did not generate player/item contact");
}

inline void sensorReclassificationTests(){
 struct Host:LiveActor {bool receiveMessage(u32,HitSensor*,HitSensor*)override{return false;}};Host a,b;NativeSensorWorld world;auto& player=world.create(1,2,1,a);auto& other=world.create(0x4a,2,1,b);world.tick();assetCheck(player.mSensorCount==1,"Initial reclassification contact missing");auto oldGroup=other.mSensorGroup;world.setType(other,1);assetCheck(other.mType==1&&other.mSensorGroup==player.mSensorGroup&&other.isValid()&&oldGroup->mSensorCount==0&&player.mSensorCount==0,"Active reclassification failed or retained contacts");world.tick();assetCheck(player.mSensorCount==0,"Player/player pair checked unexpectedly");world.setType(other,0x46);world.tick();assetCheck(player.mSensorCount==1,"Reclassified map sensor did not collide");other.invalidate();world.setType(other,0x7f);assetCheck(!other.isValid()&&other.mSensorGroup->mSensorCount==0,"Host-invalid sensor registered during reclassification");other.validate();world.tick();assetCheck(other.mSensorCount==1&&player.mSensorCount==0,"Reclassified eye sensor contact direction failed");other.invalidateBySystem();world.setType(other,0x15);assetCheck(!other.isValid()&&other.mSensorGroup->mSensorCount==0,"System-invalid sensor registered during reclassification");other.validateBySystem();world.tick();assetCheck(player.mSensorCount==1,"Reclassified system-invalid sensor failed to return");
 NativeSensorWorld bounded;for(int i=0;i<16;++i)bounded.create(1,1,1,a);auto& item=bounded.create(0x4a,1,1,b);auto itemGroup=item.mSensorGroup;bool rejected=false;try{bounded.setType(item,1);}catch(const std::exception&){rejected=true;}assetCheck(rejected&&item.mType==0x4a&&item.mSensorGroup==itemGroup&&itemGroup->mSensorCount==1,"Failed reclassification mutated sensor state");rejected=false;try{bounded.setType(player,1);}catch(const std::exception&){rejected=true;}assetCheck(rejected,"Foreign sensor reclassification accepted");
}

#include "Game/Map/ActorAppearSwitchListener.hpp"
inline void appearanceSensorLifecycleTests(){struct Player:LiveActor{int attacks=0;void attackSensor(HitSensor*,HitSensor*)override{++attacks;}} player;NativeSensorWorld world;auto& playerKeeper=world.createKeeper(NativeSensorCategory::Player,1);auto& keeper=world.createKeeper(NativeSensorCategory::Character,1);int nerveUpdates=0,hostAttacks=0;std::vector<int> attacksAtNerve;struct Host:NativeSensorLifecycleHost{int& attacks;Host(NativeSensorKeeper& keeper,int& count):NativeSensorLifecycleHost(keeper),attacks(count){}void attackSensor(HitSensor*,HitSensor*)override{++attacks;}};struct Logic:Nerve{int& updates;int& attacks;std::vector<int>& observed;Logic(int& count,int& hits,std::vector<int>& history):updates(count),attacks(hits),observed(history){}void execute(Spine*)const override{observed.push_back(attacks);++updates;}} logic(nerveUpdates,hostAttacks,attacksAtNerve);Host actor(keeper,hostAttacks);actor.initNerve(&logic);world.scheduleHost(actor);bool duplicate=false;try{world.scheduleHost(actor);}catch(const std::exception&){duplicate=true;}assetCheck(duplicate,"Duplicate lifecycle host scheduling accepted");auto& body=playerKeeper.add("body",1,2,1,player,{});auto& target=keeper.add("body",2,2,1,actor,{});playerKeeper.validate();keeper.validate();actor.mPosition={1,0,0};world.tick();assetCheck(player.attacks==1&&body.mSensorCount==1&&nerveUpdates==1,"Lifecycle sensor/nerve initial update missing");ActorAppearSwitchListener listener(&actor,true,true);listener.listenSwitchOffEvent();assetCheck(actor.isDead()&&!target.isValid()&&target.mSensorCount==0,"Switch death failed to clear/invalidate sensors");world.tick();assetCheck(player.attacks==1&&body.mSensorCount==0&&nerveUpdates==1,"Switch-dead host retained interactions or nerve updates");listener.listenSwitchOnEvent();world.tick();assetCheck(!actor.isDead()&&target.isValid()&&player.attacks==2&&nerveUpdates==2,"Switch appearance failed to restore sensors/nerve updates");target.invalidate();listener.listenSwitchOffEvent();listener.listenSwitchOnEvent();world.tick();assetCheck(!target.isValid()&&player.attacks==2,"Appearance overrode host-invalid sensor state");assetCheck(attacksAtNerve==std::vector<int>({1,2,2})&&hostAttacks==2,"Scheduled sensor dispatch order or duplicate delivery failed");world.unscheduleHost(actor);world.tick();assetCheck(nerveUpdates==3,"Detached lifecycle host nerve still advanced");world.scheduleHost(actor);world.tick();assetCheck(nerveUpdates==4,"Re-registered lifecycle host failed to advance exactly once");target.validate();world.tick();assetCheck(body.mSensorCount==1&&nerveUpdates==5,"Pre-removal lifecycle contact missing");int capacity=keeper.registeredGroup().mMaxSensors;world.retireHost(actor);actor.tickNerve();assetCheck(actor.isDead(),"Retired lifecycle host remained alive");bool detached=false;try{actor.sensorKeeper();}catch(const std::exception&){detached=true;}assetCheck(detached,"Retired host retained keeper reference");world.tick();assetCheck(body.mSensorCount==0&&nerveUpdates==5,"Removed keeper retained contacts or host callbacks");auto& replacement=world.createKeeper(NativeSensorCategory::Character,capacity);assetCheck(replacement.reservedCapacity()==capacity,"Removed keeper reservation was not released");
    struct StateLogic:Nerve{void execute(Spine* spine)const override{if(spine->mStep==1)static_cast<ActorStateBaseInterface*>(spine->mExecutor)->kill();}} stateLogic;
    struct State:ActorStateBaseInterface{int inits=0,starts=0,ends=0,updates=0;const Nerve* logic;explicit State(const Nerve* nerve):ActorStateBaseInterface("scheduled state"),logic(nerve){mIsDead=true;}void init()override{++inits;initNerve(logic);}void appear()override{ActorStateBaseInterface::appear();++starts;}void kill()override{ActorStateBaseInterface::kill();++ends;}void control()override{++updates;}};
    struct Idle:Nerve{void execute(Spine*)const override{}} idle;
    struct Active:Nerve{const Nerve* next;explicit Active(const Nerve* value):next(value){}void execute(Spine* spine)const override{static_cast<NativeSensorLifecycleHost*>(spine->mExecutor)->updateStateAndNextNerve(next);}} active(&idle);
    NativeSensorWorld stateWorld;auto& stateSensors=stateWorld.createKeeper(NativeSensorCategory::Character,1);NativeSensorLifecycleHost stateHost(stateSensors);stateHost.initNerve(&idle);stateHost.initStateKeeper(1);auto& state=stateHost.createState<State>(&active,"active",&stateLogic);stateWorld.scheduleHost(stateHost);stateHost.setNerve(&active);stateWorld.tick();assetCheck(state.inits==1&&state.starts==1&&state.updates==1&&state.ends==0,"Scheduled actor state entry/update failed");stateHost.kill();stateWorld.tick();assetCheck(state.updates==1&&state.ends==0&&state.getNerveStep()==1,"Dead host advanced actor state");stateHost.appear();stateWorld.tick();assetCheck(state.updates==1&&state.ends==1&&state.getNerveStep()==2&&stateHost.isNerve(&idle),"Resumed original actor state completion transition failed");stateWorld.tick();assetCheck(state.updates==1&&state.ends==1&&state.getNerveStep()==2,"Completed actor state updated twice");stateWorld.retireHost(stateHost);stateWorld.tick();    int destroyedStates=0;
    struct OwnedProbe:ActorStateBaseInterface{int& destroyed;bool fail;OwnedProbe(int& count,bool shouldFail):ActorStateBaseInterface("owned state probe"),destroyed(count),fail(shouldFail){mIsDead=true;}~OwnedProbe()override{++destroyed;}void init()override{if(fail)throw std::runtime_error("expected owned state init failure");}};
    {NativeSensorWorld ownershipWorld;auto& sensors=ownershipWorld.createKeeper(NativeSensorCategory::Character,1);NativeSensorLifecycleHost owner(sensors);owner.initNerve(&idle);owner.initStateKeeper(1);bool rejected=false;try{owner.createState<OwnedProbe>(&active,"failed",destroyedStates,true);}catch(const std::exception&){rejected=true;}assetCheck(rejected&&destroyedStates==1,"Failed owned state leaked");owner.createState<OwnedProbe>(&active,"owned",destroyedStates,false);rejected=false;try{owner.createState<OwnedProbe>(&active,"duplicate",destroyedStates,false);}catch(const std::exception&){rejected=true;}assetCheck(rejected&&destroyedStates==2,"Rejected owned state leaked or destroyed registered state");}
    assetCheck(destroyedStates==3,"Host did not release its owned actor state");
}










